/* Book-a-Demo modal — shared behaviour.
*
* This logic used to live inside js/feature-detail.js, a page-specific file.
* Pages that included the modal markup but not that script rendered a working
* button over a working dialog with nothing connecting them: about, careers,
* reviews, compare, team and docs all had a primary CTA that did nothing when
* clicked. Shipping it with the partial means the component always arrives
* complete.
*
* No-ops when the modal is absent, and refuses to bind twice so a page that
* also carries its own inline copy (index.php) is unaffected.
*/
(function () {
if (window.__epDemoModalBound) return;
var modal = document.getElementById('getStartedModal');
if (!modal) return;
window.__epDemoModalBound = true;
var form = document.getElementById('getStartedForm');
var countrySelect = document.getElementById('countryCode');
var whatsappInput = document.getElementById('whatsapp');
var whatsappFull = document.getElementById('whatsappFull');
var lastFocus = null;
var savedScrollY = 0;
var phonePlaceholders = {
PK: '300 1234567', US: '555 123 4567', GB: '7700 900123',
AE: '50 123 4567', SA: '50 123 4567', IN: '98765 43210'
};
function changeCountryCode() {
var iso = (countrySelect && countrySelect.value) || 'PK';
var dial = (window.getSelectedDialCode && window.getSelectedDialCode(countrySelect)) || '92';
if (whatsappInput) whatsappInput.placeholder = phonePlaceholders[iso] || 'Phone number';
if (whatsappFull && whatsappInput) {
var num = whatsappInput.value.replace(/\D/g, '');
whatsappFull.value = num ? '+' + dial + num : '';
}
}
function initCountrySelect() {
if (!countrySelect || !window.populateCountryCodeSelect) return;
window.populateCountryCodeSelect(countrySelect, (window.detectDefaultCountryIso && window.detectDefaultCountryIso()) || 'PK');
changeCountryCode();
countrySelect.addEventListener('change', changeCountryCode);
if (whatsappInput) whatsappInput.addEventListener('input', changeCountryCode);
}
function lockScroll() {
savedScrollY = window.scrollY;
document.body.classList.add('modal-open');
document.body.style.top = '-' + savedScrollY + 'px';
}
function unlockScroll() {
document.body.classList.remove('modal-open');
document.body.style.top = '';
window.scrollTo(0, savedScrollY);
}
function openModal(e) {
if (e && e.preventDefault) e.preventDefault();
lastFocus = document.activeElement;
// Carry the plan through when the click came from a pricing card, so the
// sales team knows which package prompted the enquiry.
var pkg = e && e.currentTarget && e.currentTarget.getAttribute('data-package');
var pkgField = document.getElementById('selectedPackage');
if (pkg && pkgField) pkgField.value = pkg;
modal.classList.add('open');
modal.setAttribute('aria-hidden', 'false');
lockScroll();
if (window.lucide) window.lucide.createIcons();
requestAnimationFrame(function () {
var first = document.getElementById('instituteName');
if (first) first.focus();
});
}
function closeModal() {
if (!modal.classList.contains('open')) return;
modal.classList.remove('open');
modal.setAttribute('aria-hidden', 'true');
unlockScroll();
if (lastFocus && document.contains(lastFocus)) lastFocus.focus();
}
document.querySelectorAll('.js-open-modal').forEach(function (btn) {
btn.addEventListener('click', openModal);
});
var cancel = document.getElementById('modalCancel');
if (cancel) cancel.addEventListener('click', closeModal);
modal.addEventListener('click', function (e) { if (e.target === modal) closeModal(); });
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && modal.classList.contains('open')) closeModal();
});
if (form) {
form.addEventListener('submit', function (e) {
e.preventDefault();
changeCountryCode();
if (!window.handleLeadFormSubmit) return;
window.handleLeadFormSubmit(form, { onSuccess: closeModal, onReset: initCountrySelect });
});
}
initCountrySelect();
})();